begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_table('public','classrooms','classrooms exist');
select has_table('public','classroom_enrollments','email enrollments exist');
select has_table('public','classroom_assignments','class assignments exist');
select has_table('public','teaching_case_drafts','private author drafts exist');
select has_table('public','teacher_feedback','teacher feedback exists');
select ok(not has_table_privilege('authenticated','private.teacher_allowlist','select'),'teacher allowlist cannot be read by browsers');
select ok(not has_table_privilege('authenticated','private.teacher_allowlist','insert'),'a browser cannot grant itself teacher access');
select ok(not has_function_privilege('authenticated','private.build_simulation_debrief(uuid,uuid)','execute'),'raw cross-owner debrief builder is not executable');
select ok(not has_function_privilege('anon','public.teaching_bootstrap()','execute'),'Google bootstrap requires authentication');
select ok(not has_function_privilege('anon','public.teaching_get_debrief(uuid)','execute'),'teacher debrief cannot be called by anon');
select is((select count(*)::integer from pg_tables where schemaname='public' and tablename in ('classrooms','classroom_enrollments','classroom_assignments','teaching_case_drafts','teacher_feedback') and rowsecurity),5,'every classroom table has RLS');
select ok(not has_table_privilege('authenticated','public.classroom_assignments','insert') and not has_table_privilege('authenticated','public.teacher_feedback','update'),'management writes require authorization RPCs');
select is((select count(*)::integer from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and (p.proname like 'teaching_%' or p.proname='student_workspace') and p.prosecdef),0,'new public management facades never bypass RLS');
select is((select count(*)::integer from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and (p.proname like 'teaching_%' or p.proname='student_workspace') and p.proconfig[1] in ('search_path=','search_path=""')),13,'all management facades pin an empty search_path');
select has_column('public','simulation_sessions','assignment_id','attempts are bound to a classroom activity');
select has_column('public','simulation_sessions','classroom_student_email','submitted student email is retained');
select has_index('public','simulation_sessions','simulation_sessions_one_active_per_activity_idx','one active attempt per user, case and activity');
select ok(not has_function_privilege('authenticated','private.resolve_simulation_transition_internal(uuid,uuid,text)','execute'),'answer resolver cannot be called directly by the browser role');
select * from finish();
rollback;
